-- ── kutai-yupa-borneo ── registry only 235 chars — a blurb; needs writing
--    real languages: as,bn,en,hi,kn,pa,pn,ta,te
--    LEAVE AS DRAFT — body is a blurb, not an article
UPDATE srangam_articles SET
  content = jsonb_build_object(
    'as', $body$কুটাইৰ সাতটা যূপ শিলালিপিয়ে দক্ষিণ-পূৱ এছিয়াৰ আটাইতকৈ গুৰুত্বপূৰ্ণ প্ৰত্নতাত্ত্বিক আৱিষ্কাৰৰ এটাৰ প্ৰতিনিধিত্ব কৰে...$body$,
    'bn', $body$কুটাইয়ের সাতটি যূপ লিপি দক্ষিণ-পূর্ব এশিয়ার সর্বাধিক গুরুত্বপূর্ণ প্রত্নতাত্ত্বিক আবিষ্কারগুলির মধ্যে একটি প্রতিনিধিত্ব করে...$body$,
    'en', $body$The seven yūpa inscriptions of Kutai represent one of the most significant archaeological discoveries in Southeast Asia, providing our earliest evidence of Sanskrit culture and Hindu-Buddhist traditions in the Indonesian archipelago...$body$,
    'hi', $body$कुटै के सात यूप अभिलेख दक्षिण-पूर्व एशिया की सबसे महत्वपूर्ण पुरातत्व खोजों में से एक का प्रतिनिधित्व करते हैं...$body$,
    'kn', $body$ಕುಟೈನ ಏಳು ಯೂಪ ಶಾಸನಗಳು ಆಗ್ನೇಯ ಏಷ್ಯಾದ ಅತ್ಯಂತ ಮಹತ್ವದ ಪುರಾತತ್ವ ಆವಿಷ್ಕಾರಗಳಲ್ಲಿ ಒಂದನ್ನು ಪ್ರತಿನಿಧಿಸುತ್ತವೆ...$body$,
    'pa', $body$ਕੁਟੈ ਦੇ ਸੱਤ ਯੂਪ ਅਭਿਲੇਖ ਦੱਖਣ-ਪੂਰਬੀ ਏਸ਼ੀਆ ਦੀਆਂ ਸਭ ਤੋਂ ਮਹੱਤਵਪੂਰਨ ਪੁਰਾਤੱਤਵ ਖੋਜਾਂ ਵਿੱਚੋਂ ਇੱਕ ਦੀ ਨੁਮਾਇੰਦਗੀ ਕਰਦੇ ਹਨ...$body$,
    'pn', $body$Ka khyndaw yūpa jinglong ha Kutai ki pynbna ka pyrthei jingkham ha Southeast Asia ki bnah ka pyrkhat thaw...$body$,
    'ta', $body$குடையின் ஏழு யூப கல்வெட்டுகள் தென்கிழக்கு ஆசியாவின் மிக முக்கியமான தொல்பொருள் கண்டுபிடிப்புகளில் ஒன்றாகும்...$body$,
    'te', $body$కుటై యొక్క ఏడు యూప శాసనాలు ఆగ్నేయ ఆసియాలోని అత్యంత ముఖ్యమైన పురావస్తు ఆవిష్కరణలలో ఒకటిగా ప్రాతినిధ్యం వహిస్తున్నాయి...$body$
  ),
  updated_at = now()
WHERE slug = 'kutai-yupa-borneo'
  AND length(COALESCE(content::jsonb ->> 'en','')) < 200   -- shell only; idempotent
RETURNING slug, status, length(content::jsonb ->> 'en') AS en_chars;

